/* global React, BU_DATA, BrainGraph3D,
          LevelGlyph, CertBadge, MasteryMeter, TierPill, StageChip,
          LineChart, StatCard, EvidenceList, SectionTitle */

const { useState, useMemo, useEffect } = React;

// ─────────────────────────────────────────────────────────────────
// AGENT VIEW — AGENTS
// Roster of enrolled/certified agents + a fully interpretable
// profile: skill graph, certifications → evidence, progress,
// report card, failure transparency, governance, memory.
// Reads window.ATP_DATA (generated by scripts/build_atp_data.py).
// ─────────────────────────────────────────────────────────────────

const ATP_GOLD = "var(--c-cert, #e8c268)";

// Skill status → color. css for 2D chrome (theme-aware), hex for WebGL
// (three.js can't resolve CSS variables).
const SKILL_STATUS = {
  strong:     { label: "strong",     css: "var(--c-cs, #2ec4b6)",      hex: "#2ec4b6" },
  developing: { label: "developing", css: "var(--c-bridge, #7dd3fc)",  hex: "#7dd3fc" },
  weak:       { label: "weak",       css: "var(--c-here, #f96167)",    hex: "#f96167" },
  untested:   { label: "untested",   css: "var(--c-ink-dim, #5d6688)", hex: "rgba(155,170,200,0.40)" },
};

const AGENT_STATUS_META = {
  active:   { label: "active",   color: "var(--c-cs, #2ec4b6)" },
  training: { label: "training", color: "var(--c-visited, #fbb036)" },
  revoked:  { label: "revoked",  color: "var(--c-here, #f96167)" },
};

// BrainGraph3D colors nodes via BU_DATA.CLUSTERS[node.cluster]. Register four
// ATP pseudo-clusters as *named keys* on the CLUSTERS array (additive — no BU
// node ever references them) so skill nodes color by STATUS, not by course.
function _ensureStatusClusters() {
  try {
    const C = window.BU_DATA && window.BU_DATA.CLUSTERS;
    if (!C || C.atpStrong) return;
    C.atpStrong     = { name: "strong skill",     color: SKILL_STATUS.strong.hex,     blurb: "" };
    C.atpDeveloping = { name: "developing skill", color: SKILL_STATUS.developing.hex, blurb: "" };
    C.atpWeak       = { name: "weak skill",       color: SKILL_STATUS.weak.hex,       blurb: "" };
    C.atpUntested   = { name: "untested skill",   color: SKILL_STATUS.untested.hex,   blurb: "" };
  } catch (_) { /* BU_DATA not loaded — 3D graph is skipped anyway */ }
}

function _statusClusterKey(status) {
  return { strong: "atpStrong", developing: "atpDeveloping", weak: "atpWeak" }[status] || "atpUntested";
}

function _certOf(A, id) {
  if (!A) return null;
  try { if (typeof A.certById === "function") return A.certById(id) || null; } catch (_) {}
  return (A.CERTS || []).find(c => c.id === id) || null;
}

function _pct(x) { return Math.round((x || 0) * 100) + "%"; }

// ── Deep-link helpers (hash router lives in Brain University.html) ──
// Deep links: #/agent/{id} and #/cert/{id} — docs/HARDENING.md Phase 3.
// (Names are file-local on purpose: screens share the page's global scope.)

function agentsDeepUrl(hashPath) {
  return window.location.href.split("#")[0] + "#" + hashPath;
}

async function agentsCopyText(text) {
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch (_) { /* fall through to execCommand */ }
  try {
    const ta = document.createElement("textarea");
    ta.value = text;
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    const ok = document.execCommand("copy");
    document.body.removeChild(ta);
    return ok;
  } catch (_) { return false; }
}

// Small mono "copy link" affordance with transient copied/failed feedback.
function AgentsCopyLink({ hashPath, label = "⧉ copy link", title }) {
  const [state, setState] = useState("idle"); // idle | copied | failed
  return (
    <button
      type="button"
      className="btn ghost"
      title={title || `Copy deep link — ${hashPath}`}
      onClick={async (e) => {
        e.stopPropagation();
        const ok = await agentsCopyText(agentsDeepUrl(hashPath));
        setState(ok ? "copied" : "failed");
        setTimeout(() => setState("idle"), 1600);
      }}
      style={{
        padding: "2px 7px", fontSize: 10.5, fontFamily: "var(--f-mono)",
        flexShrink: 0, whiteSpace: "nowrap",
        color: state === "copied" ? "var(--c-cs, #2ec4b6)"
             : state === "failed" ? "var(--c-here)" : undefined,
      }}
    >
      {state === "copied" ? "✓ copied" : state === "failed" ? "copy failed" : label}
    </button>
  );
}

// Gold provenance chip — commissioned agents wear their training origin openly.
function AgentProvenanceChip({ provenance }) {
  if (!provenance || provenance.origin !== "commissioned") return null;
  return (
    <span className="tag" style={{
      color: ATP_GOLD, fontFamily: "var(--f-mono)", fontSize: 10,
      borderColor: "color-mix(in oklch, #e8c268 50%, transparent)",
    }}>
      trained-to-order · corpus: {(provenance.corpora || []).join("/")}
    </span>
  );
}

function AgentStatusTag({ status, compact }) {
  const m = AGENT_STATUS_META[status] || AGENT_STATUS_META.active;
  return (
    <span className="t-mono" style={{
      fontSize: compact ? 9.5 : 10.5, textTransform: "uppercase", letterSpacing: "0.08em",
      color: m.color, whiteSpace: "nowrap",
    }}>
      {status === "revoked" ? "⚠ " : "● "}{m.label}
    </span>
  );
}

// ── Left rail — roster ──────────────────────────────────────────

function AgentRosterRow({ a, active, onPick }) {
  const revoked = a.status === "revoked";
  return (
    <div onClick={onPick} style={{
      display: "flex", alignItems: "center", gap: 10, padding: "10px 12px",
      cursor: "pointer", borderBottom: "1px solid var(--c-line)",
      borderLeft: revoked
        ? "3px solid var(--c-here)"
        : (active ? `3px solid ${ATP_GOLD}` : "3px solid transparent"),
      background: active
        ? "color-mix(in oklch, var(--c-bridge) 7%, transparent)"
        : (revoked ? "color-mix(in oklch, var(--c-here) 5%, transparent)" : "transparent"),
    }}>
      <span style={{ fontSize: 19, lineHeight: 1 }}>{a.emoji}</span>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <span style={{
            fontWeight: 600, fontSize: 13.5,
            whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis",
            color: revoked ? "var(--c-here)" : "var(--c-ink)",
          }}>{a.name}</span>
          <LevelGlyph n={a.level} size={16} />
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 4, flexWrap: "wrap" }}>
          <StageChip stage={a.careerStage} />
          <TierPill tier={a.tier} />
        </div>
      </div>
      <AgentStatusTag status={a.status} compact />
    </div>
  );
}

function AgentRoster({ agents, selectedIdActual, onPick, q, setQ, levelFilter, setLevelFilter }) {
  const inputStyle = {
    width: "100%", background: "var(--c-bg-elev-2)",
    border: "1px solid var(--c-line-strong)", borderRadius: "var(--r-md)",
    padding: "7px 10px", color: "var(--c-ink)", outline: "none",
    fontFamily: "var(--f-sans)", fontSize: 13,
  };
  return (
    <div className="card" style={{ padding: 0, overflow: "hidden", position: "sticky", top: 72 }}>
      <div style={{ padding: 12, borderBottom: "1px solid var(--c-line)", display: "flex", gap: 8 }}>
        <input
          value={q} onChange={e => setQ(e.target.value)}
          placeholder="Search name / model / domain…"
          style={inputStyle}
        />
        <select
          value={levelFilter} onChange={e => setLevelFilter(e.target.value)}
          style={{ ...inputStyle, width: 74, fontFamily: "var(--f-mono)", fontSize: 12 }}
        >
          <option value="all">L·all</option>
          {[1, 2, 3, 4, 5, 6, 7].map(n => <option key={n} value={n}>L{n}</option>)}
        </select>
      </div>
      <div style={{ maxHeight: "calc(100vh - 220px)", overflowY: "auto" }}>
        {agents.map(a => (
          <AgentRosterRow key={a.id} a={a} active={a.id === selectedIdActual} onPick={() => onPick(a.id)} />
        ))}
        {agents.length === 0 && (
          <div className="t-cap" style={{ padding: 16 }}>No agents match this filter.</div>
        )}
      </div>
    </div>
  );
}

// ── Profile sections ────────────────────────────────────────────

function AgentHeaderCard({ A, agent }) {
  const revoked = agent.status === "revoked";
  const levelDef = A.STANDARD && A.STANDARD.levels && A.STANDARD.levels["L" + agent.level];
  const lic = agent.licensing || {};
  const revokeEvent = revoked
    ? [...(agent.history || [])].reverse().find(h => h.kind === "revoke")
    : null;
  return (
    <div className="card" style={{
      borderTop: `2px solid ${revoked ? "var(--c-here)" : ATP_GOLD}`,
      display: "flex", flexDirection: "column", gap: 12,
    }}>
      <div style={{ display: "flex", gap: 16, alignItems: "flex-start", flexWrap: "wrap" }}>
        <div style={{
          width: 56, height: 56, borderRadius: "50%", flexShrink: 0,
          display: "flex", alignItems: "center", justifyContent: "center", fontSize: 28,
          background: "var(--c-bg-elev-2)",
          border: `1.5px solid ${revoked ? "var(--c-here)" : "color-mix(in oklch, #e8c268 55%, transparent)"}`,
          boxShadow: "inset 0 0 0 3px var(--c-bg-elev)",
        }}>{agent.emoji}</div>
        <div style={{ flex: 1, minWidth: 220 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
            <div className="t-tag" style={{ color: "var(--c-ink-muted)" }}>
              {agent.baseModel} · {agent.id}
            </div>
            <AgentsCopyLink hashPath={"/agent/" + encodeURIComponent(agent.id)}
              title={`Copy agent deep link — #/agent/${agent.id}`} />
          </div>
          <h1 className="t-h1" style={{ margin: "4px 0 6px" }}>{agent.name}</h1>
          <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
            <LevelGlyph n={agent.level} size={22} />
            <span className="t-mono" style={{ fontSize: 12, color: "var(--c-ink-muted)" }}>
              L{agent.level}{levelDef ? ` — ${levelDef.title}` : ""}
            </span>
            <StageChip stage={agent.careerStage} />
            <TierPill tier={agent.tier} />
            <AgentStatusTag status={agent.status} />
          </div>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 8 }}>
            {(agent.domains || []).map(d => <span key={d} className="tag">{d}</span>)}
            <AgentProvenanceChip provenance={agent.provenance} />
          </div>
        </div>
        <div style={{ textAlign: "right", minWidth: 130 }}>
          <div className="t-tag" style={{ color: "var(--c-ink-muted)", marginBottom: 4 }}>LICENSING</div>
          {lic.available ? (
            <React.Fragment>
              <div className="t-num" style={{ color: ATP_GOLD }}>{lic.price}</div>
              <div className="t-cap" style={{ marginTop: 3 }}>{lic.licensees || 0} licensee{(lic.licensees || 0) === 1 ? "" : "s"}</div>
            </React.Fragment>
          ) : (
            <div className="t-cap">not licensed for external use</div>
          )}
        </div>
      </div>
      {revoked && (
        <div className="card recessed" style={{
          padding: "10px 14px", borderLeft: "3px solid var(--c-here)",
          background: "color-mix(in oklch, var(--c-here) 7%, transparent)",
        }}>
          <span className="t-tag" style={{ color: "var(--c-here)" }}>⚠ CERTIFICATION REVOKED</span>
          <div className="t-cap" style={{ marginTop: 4 }}>
            {revokeEvent ? `${revokeEvent.ts} — ${revokeEvent.event}` :
              "Sustained quality collapse below the EWMA threshold."}{" "}
            The revocation stays on the record — principle 5 of the ATP standard.
          </div>
        </div>
      )}
    </div>
  );
}

function SkillGraphSection({ agent }) {
  _ensureStatusClusters();
  const skills = agent.skills || [];
  const has3D = Boolean(window.BrainGraph3D && window.BU_DATA && skills.length);

  const customNodes = useMemo(() => skills.map(s => ({
    id: s.id, name: s.name,
    cluster: _statusClusterKey(s.status),        // → status color in 3D
    degree: Math.max(1, Math.round((s.mastery || 0) * 10)), // → node size by mastery
    layer: s.layer,
  })), [agent.id]);

  const customLinks = useMemo(() => {
    const ids = new Set(skills.map(s => s.id));
    return (agent.skillEdges || []).filter(e => ids.has(e[0]) && ids.has(e[1]));
  }, [agent.id]);

  const counts = useMemo(() => {
    const c = { strong: 0, developing: 0, weak: 0, untested: 0 };
    skills.forEach(s => { c[s.status] = (c[s.status] || 0) + 1; });
    return c;
  }, [agent.id]);

  const sorted = useMemo(() =>
    [...skills].sort((a, b) => {
      if ((a.status === "untested") !== (b.status === "untested")) return a.status === "untested" ? 1 : -1;
      return (b.mastery || 0) - (a.mastery || 0);
    }), [agent.id]);

  return (
    <div className="card">
      <SectionTitle kicker="COMPETENCY MAP" title="Skill graph" />
      <p className="t-cap" style={{ margin: "6px 0 12px" }}>
        Node size = mastery · color = status. Untested skills are deliberately visible —
        uncertainty is part of the record.
      </p>
      {has3D && (
        <div style={{
          height: 340, borderRadius: "var(--r-md)", overflow: "hidden",
          border: "1px solid var(--c-line)", background: "var(--c-bg-elev-2)",
        }}>
          <BrainGraph3D
            key={agent.id}
            customNodes={customNodes}
            customLinks={customLinks}
            showLabels="all"
            linkOpacity={0.5}
            background="var(--c-bg-elev-2)"
          />
        </div>
      )}
      {/* 2D legend (always shown — it doubles as the fallback key) */}
      <div style={{ display: "flex", gap: 16, flexWrap: "wrap", margin: "12px 0 4px" }}>
        {Object.entries(SKILL_STATUS).map(([k, m]) => (
          <span key={k} className="t-mono" style={{ fontSize: 11, color: "var(--c-ink-muted)" }}>
            <span style={{
              display: "inline-block", width: 9, height: 9, borderRadius: "50%",
              background: m.css, marginRight: 6, verticalAlign: "middle",
              opacity: k === "untested" ? 0.55 : 1,
              outline: k === "untested" ? "1px dashed var(--c-ink-dim)" : "none",
            }} />
            {m.label} · {counts[k] || 0}
          </span>
        ))}
      </div>
      {!has3D && (
        <div className="t-cap" style={{ marginBottom: 8, color: "var(--c-ink-dim)" }}>
          3D graph unavailable — showing the skill list only.
        </div>
      )}
      {/* Per-skill list w/ mastery + confidence + status */}
      <div style={{ marginTop: 8 }}>
        {sorted.map(s => (
          <div key={s.id} style={{
            display: "grid", gridTemplateColumns: "minmax(150px, 1.1fr) 1fr 76px",
            gap: 12, alignItems: "center", padding: "8px 0",
            borderBottom: "1px solid var(--c-line)",
          }}>
            <div style={{ minWidth: 0 }}>
              <span style={{ fontWeight: 600, fontSize: 13 }}>{s.name}</span>
              <span className="t-mono" style={{ marginLeft: 8, fontSize: 10, color: "var(--c-ink-dim)" }}>
                L{s.layer}
              </span>
            </div>
            <MasteryMeter value={s.mastery} confidence={s.confidence} status={s.status} />
            <span className="t-mono" style={{
              fontSize: 11, textAlign: "right",
              color: (SKILL_STATUS[s.status] || SKILL_STATUS.untested).css,
            }}>
              {s.status === "untested" ? "untested" : `${_pct(s.mastery)} ±${Math.round((1 - (s.confidence || 0)) * 100)}`}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

function CertificationsSection({ A, agent }) {
  const [openId, setOpenId] = useState(null);
  const certs = (agent.certIds || []).map(id => _certOf(A, id)).filter(Boolean);
  const open = certs.find(c => c.id === openId) || null;
  const award = open ? (open.awards || []).find(w => w.agentId === agent.id) : null;

  return (
    <div className="card">
      <SectionTitle kicker="CREDENTIALS" title="Certifications" />
      <p className="t-cap" style={{ margin: "6px 0 12px" }}>
        Click a seal — its meaning is one click away, always.
      </p>
      {certs.length === 0 && (
        <div className="t-cap" style={{ color: "var(--c-ink-dim)" }}>
          No certifications yet — this agent is still working through the curriculum.
        </div>
      )}
      <div style={{ display: "flex", gap: 12, flexWrap: "wrap", alignItems: "center" }}>
        {certs.map(c => (
          <div key={c.id} style={{
            display: "flex", flexDirection: "column", alignItems: "center", gap: 2,
          }}>
            <CertBadge cert={c} size={48}
              onClick={() => setOpenId(openId === c.id ? null : c.id)} />
            <AgentsCopyLink hashPath={"/cert/" + encodeURIComponent(c.id)}
              label="⧉ link" title={`Copy cert deep link — #/cert/${c.id}`} />
          </div>
        ))}
        <AgentProvenanceChip provenance={agent.provenance} />
      </div>

      {open && (
        <div className="card recessed slide-up" style={{
          marginTop: 14, padding: 16, borderLeft: `3px solid ${ATP_GOLD}`,
        }}>
          <div className="t-tag" style={{ color: ATP_GOLD, marginBottom: 6 }}>
            CERTIFIED BECAUSE OF:
          </div>
          <div className="t-mono" style={{ fontSize: 12, marginBottom: 4 }}>{open.label}</div>
          <p style={{ margin: "0 0 12px", fontSize: 14, fontStyle: "italic", color: "var(--c-ink-muted)" }}>
            “{open.sentence}”
          </p>
          {award ? (
            <React.Fragment>
              <div style={{ display: "flex", gap: 18, flexWrap: "wrap", marginBottom: 10 }}>
                <span className="t-mono" style={{ fontSize: 12 }}>
                  score <span style={{ color: ATP_GOLD, fontWeight: 600 }}>{_pct(award.score)}</span>
                </span>
                <span className="t-mono" style={{ fontSize: 12 }}>
                  awarded <span style={{ color: "var(--c-ink-muted)" }}>{award.ts}</span>
                </span>
                {award.itemBreakdown && (
                  <span className="t-mono" style={{ fontSize: 12 }}>
                    items:{" "}
                    <span style={{ color: "var(--c-cs, #2ec4b6)" }}>{award.itemBreakdown.passed} passed</span>{" · "}
                    <span style={{ color: "var(--c-here)" }}>{award.itemBreakdown.failed} failed</span>{" · "}
                    <span style={{ color: "var(--c-visited)" }}>{award.itemBreakdown.flagged} flagged</span>
                  </span>
                )}
              </div>
              {award.sectionScores && (
                <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>
                  {Object.entries(award.sectionScores).map(([name, sc]) => (
                    <span key={name} className="tag" style={{ fontFamily: "var(--f-mono)", fontSize: 10.5 }}>
                      {name} {_pct(sc)}
                    </span>
                  ))}
                </div>
              )}
              <div className="t-tag" style={{ color: "var(--c-ink-muted)", margin: "10px 0 6px" }}>
                EVIDENCE TRAIL · {(award.evidenceIds || []).length} RECORDS
              </div>
              <EvidenceList ids={award.evidenceIds || []} />
            </React.Fragment>
          ) : (
            <div className="t-cap">No award record found for this agent on this certification.</div>
          )}
        </div>
      )}
    </div>
  );
}

function ProgressSection({ agent }) {
  const prog = agent.progress || [];
  const maxCerts = Math.max(1, ...prog.map(p => p.certs || 0));
  const latest = prog[prog.length - 1] || {};
  const series = [
    { label: "mastery", color: "#7dd3fc", points: prog.map(p => ({ ts: p.ts, value: p.mastery || 0 })) },
    { label: "certifications (scaled)", color: "#e8c268", points: prog.map(p => ({ ts: p.ts, value: (p.certs || 0) / maxCerts })) },
  ];
  return (
    <div className="card">
      <SectionTitle kicker="TRANSCRIPT" title="Progress over time" />
      <div style={{ margin: "12px 0 8px" }}>
        <LineChart series={series} height={180} yLabel="mastery 0–1" />
      </div>
      <div style={{ display: "flex", gap: 16, flexWrap: "wrap" }}>
        <span className="t-mono" style={{ fontSize: 11, color: "var(--c-ink-muted)" }}>
          <span style={{ color: "#7dd3fc" }}>—</span> mastery (now {_pct(latest.mastery)})
        </span>
        <span className="t-mono" style={{ fontSize: 11, color: "var(--c-ink-muted)" }}>
          <span style={{ color: "#e8c268" }}>—</span> certifications, scaled ×1/{maxCerts} (now {latest.certs || 0})
        </span>
        <span className="t-mono" style={{ fontSize: 11, color: "var(--c-ink-dim)" }}>
          currently at L{latest.layer || agent.level}
        </span>
      </div>
    </div>
  );
}

function ReportCardSection({ agent }) {
  const rc = agent.reportCard || {};
  const asOf = (agent.progress || []).slice(-1)[0];
  return (
    <div className="card" style={{ borderTop: `2px solid ${ATP_GOLD}` }}>
      <div style={{
        display: "flex", justifyContent: "space-between", alignItems: "baseline",
        borderBottom: "1px solid var(--c-line)", paddingBottom: 10, marginBottom: 12,
      }}>
        <SectionTitle kicker="OFFICE OF THE REGISTRAR" title="Report card" />
        <span className="t-mono" style={{ fontSize: 11, color: "var(--c-ink-dim)" }}>
          {agent.name} · {asOf ? "as of " + asOf.ts : "current term"}
        </span>
      </div>
      <p style={{ margin: "0 0 14px", fontSize: 15, lineHeight: 1.6 }}>{rc.summary}</p>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 14 }}>
        <div>
          <div className="t-tag" style={{ color: "var(--c-cs, #2ec4b6)", marginBottom: 6 }}>STRENGTHS</div>
          {(rc.strengths || []).map((s, i) => (
            <div key={i} className="t-cap" style={{ fontSize: 13, marginBottom: 5, color: "var(--c-ink)" }}>
              <span style={{ color: "var(--c-cs, #2ec4b6)", marginRight: 6 }}>✓</span>{s}
            </div>
          ))}
        </div>
        <div>
          <div className="t-tag" style={{ color: "var(--c-here)", marginBottom: 6 }}>NEEDS WORK</div>
          {(rc.weaknesses || []).map((s, i) => (
            <div key={i} className="t-cap" style={{ fontSize: 13, marginBottom: 5, color: "var(--c-ink)" }}>
              <span style={{ color: "var(--c-here)", marginRight: 6 }}>△</span>{s}
            </div>
          ))}
        </div>
      </div>
      {rc.recommendation && (
        <div className="card recessed" style={{ marginTop: 14, padding: 14, borderLeft: `3px solid ${ATP_GOLD}` }}>
          <div className="t-tag" style={{ color: ATP_GOLD, marginBottom: 5 }}>REGISTRAR'S RECOMMENDATION</div>
          <div style={{ fontSize: 14, lineHeight: 1.55 }}>{rc.recommendation}</div>
        </div>
      )}
    </div>
  );
}

function FailureSection({ agent }) {
  const failures = agent.failures || [];
  return (
    <div className="card" style={{ borderLeft: "3px solid var(--c-here)" }}>
      <SectionTitle kicker="FAILURE TRANSPARENCY" title="Where this agent fails" />
      <p className="t-cap" style={{ margin: "6px 0 12px" }}>
        Published alongside every pass — principle 4 of the ATP standard. An agent you can
        trust is one whose limits are on the record, not hidden in a footnote.
      </p>
      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", minWidth: 560 }}>
          <thead>
            <tr>
              {["FAILURE MODE", "RATE", "EXAMPLE", "LIKELY BOUNDARY"].map(h => (
                <th key={h} className="t-tag" style={{
                  textAlign: "left", color: "var(--c-ink-muted)",
                  padding: "6px 12px 6px 0", borderBottom: "1px solid var(--c-line-strong)",
                  fontWeight: 500,
                }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {failures.map((f, i) => (
              <tr key={i}>
                <td style={{ padding: "10px 12px 10px 0", borderBottom: "1px solid var(--c-line)", fontWeight: 600, fontSize: 13, verticalAlign: "top" }}>
                  {f.mode}
                </td>
                <td className="t-mono" style={{ padding: "10px 12px 10px 0", borderBottom: "1px solid var(--c-line)", color: "var(--c-here)", fontSize: 12, verticalAlign: "top", whiteSpace: "nowrap" }}>
                  {(Math.round((f.rate || 0) * 1000) / 10)}%
                </td>
                <td className="t-cap" style={{ padding: "10px 12px 10px 0", borderBottom: "1px solid var(--c-line)", fontSize: 12.5, verticalAlign: "top" }}>
                  {f.example}
                </td>
                <td className="t-cap" style={{ padding: "10px 0", borderBottom: "1px solid var(--c-line)", fontSize: 12.5, fontStyle: "italic", verticalAlign: "top" }}>
                  {f.boundary}
                </td>
              </tr>
            ))}
            {failures.length === 0 && (
              <tr><td colSpan={4} className="t-cap" style={{ padding: "10px 0" }}>
                No failure modes recorded yet — which mostly means it hasn't been tested hard enough.
              </td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function GovernanceSection({ A, agent }) {
  const tier = (A.TIERS || {})[agent.tier];
  const policies = (A.POLICIES || []).filter(p =>
    (agent.policyIds || []).includes(p.id) || (p.bindsAgentIds || []).includes(agent.id));
  return (
    <div className="card">
      <SectionTitle kicker="GOVERNANCE" title="Permissions & policy bindings" />
      <div style={{ display: "flex", alignItems: "center", gap: 10, margin: "10px 0 12px", flexWrap: "wrap" }}>
        <TierPill tier={agent.tier} />
        {tier && (
          <span className="tag" style={{ fontFamily: "var(--f-mono)", fontSize: 10.5 }}>
            sandbox: {tier.sandbox}
          </span>
        )}
      </div>
      {tier && (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: 14 }}>
          <div>
            <div className="t-tag" style={{ color: "var(--c-cs, #2ec4b6)", marginBottom: 6 }}>MAY</div>
            {(tier.may || []).map((s, i) => (
              <div key={i} className="t-cap" style={{ fontSize: 13, marginBottom: 5, color: "var(--c-ink)" }}>
                <span style={{ color: "var(--c-cs, #2ec4b6)", marginRight: 6 }}>✓</span>{s}
              </div>
            ))}
          </div>
          <div>
            <div className="t-tag" style={{ color: "var(--c-here)", marginBottom: 6 }}>MAY NOT</div>
            {(tier.mayNot || []).map((s, i) => (
              <div key={i} className="t-cap" style={{ fontSize: 13, marginBottom: 5, color: "var(--c-ink)" }}>
                <span style={{ color: "var(--c-here)", marginRight: 6 }}>✕</span>{s}
              </div>
            ))}
          </div>
        </div>
      )}
      <div className="t-tag" style={{ color: "var(--c-ink-muted)", margin: "14px 0 8px" }}>
        BOUND POLICIES · {policies.length}
      </div>
      {policies.map(p => (
        <div key={p.id} style={{ padding: "8px 0", borderBottom: "1px solid var(--c-line)" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
            <span style={{ fontWeight: 600, fontSize: 13 }}>{p.name}</span>
            <span className="tag" style={{ fontFamily: "var(--f-mono)", fontSize: 10 }}>
              {(p.kind || "").replace(/_/g, " ")}
            </span>
          </div>
          <div className="t-cap" style={{ marginTop: 3, fontSize: 12.5 }}>{p.summary}</div>
        </div>
      ))}
      {policies.length === 0 && (
        <div className="t-cap" style={{ color: "var(--c-ink-dim)" }}>No policies bound to this agent.</div>
      )}
    </div>
  );
}

function MemorySection({ agent, goto }) {
  const m = agent.memory || {};
  const fmt = n => (n == null ? "—" : Number(n).toLocaleString());
  return (
    <div className="card">
      <SectionTitle kicker="MEMORY" title="Vault-LD" />
      <p className="t-cap" style={{ margin: "6px 0 12px" }}>
        What this agent has consolidated into structured, linked memory.
      </p>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(130px, 1fr))", gap: 10 }}>
        <StatCard label="Wiki pages" value={fmt(m.wikiPages)} />
        <StatCard label="KG nodes" value={fmt(m.kgNodes)} />
        <StatCard label="KG edges" value={fmt(m.kgEdges)} />
        <StatCard label="Ontology classes" value={fmt(m.ontologyClasses)} />
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 12, flexWrap: "wrap", gap: 8 }}>
        <span className="t-mono" style={{ fontSize: 11, color: "var(--c-ink-dim)" }}>
          last consolidation: {m.lastConsolidation || "—"}
        </span>
        <button className="btn" onClick={() => goto && goto("vault")}>Open Vault-LD →</button>
      </div>
    </div>
  );
}

function AgentProfile({ A, agent, goto }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16, minWidth: 0 }}>
      <AgentHeaderCard A={A} agent={agent} />
      <SkillGraphSection agent={agent} />
      <CertificationsSection A={A} agent={agent} />
      <ProgressSection agent={agent} />
      <ReportCardSection agent={agent} />
      <FailureSection agent={agent} />
      <GovernanceSection A={A} agent={agent} />
      <MemorySection agent={agent} goto={goto} />
    </div>
  );
}

// ── Screen ──────────────────────────────────────────────────────

function ATPAgents({ selectedId, onSelect, goto }) {
  const A = window.ATP_DATA;
  const agents = (A && A.AGENTS) || [];

  const [q, setQ] = useState("");
  const [levelFilter, setLevelFilter] = useState("all");
  const [localId, setLocalId] = useState(selectedId || null);
  useEffect(() => { if (selectedId) setLocalId(selectedId); }, [selectedId]);

  const roster = useMemo(() => {
    const needle = q.trim().toLowerCase();
    return agents.filter(a => {
      if (levelFilter !== "all" && a.level !== Number(levelFilter)) return false;
      if (!needle) return true;
      return [a.name, a.baseModel, ...(a.domains || [])].join(" ").toLowerCase().includes(needle);
    });
  }, [agents, q, levelFilter]);

  if (!A) {
    return (
      <div style={{ minHeight: "calc(100vh - 56px)", display: "grid", placeItems: "center", padding: 24 }}>
        <div className="card" style={{ maxWidth: 480, textAlign: "center" }}>
          <div className="t-h2" style={{ marginBottom: 8 }}>ATP data not loaded</div>
          <p className="t-cap">
            Run <code>python3 scripts/build_atp_data.py</code> to generate{" "}
            <code>design/atp_data.js</code>, then reload.
          </p>
        </div>
      </div>
    );
  }

  const agent = agents.find(a => a.id === localId) || roster[0] || agents[0] || null;
  const pick = id => { setLocalId(id); if (onSelect) onSelect(id); };

  return (
    <div style={{ minHeight: "calc(100vh - 56px)", padding: "32px 28px 80px" }}>
      <div style={{ maxWidth: 1240, margin: "0 auto" }}>
        <SectionTitle kicker="AGENT UNIVERSITY · REGISTRY" title="Agents" />
        <p className="t-cap" style={{ margin: "6px 0 0", maxWidth: 640 }}>
          Every agent's certification level, evidence trail, failure modes and permissions —
          in plain sight. Meaning is one click away.
        </p>
        <div style={{
          display: "grid", gridTemplateColumns: "minmax(250px, 300px) 1fr",
          gap: 16, alignItems: "start", marginTop: 22,
        }}>
          <AgentRoster
            agents={roster}
            selectedIdActual={agent ? agent.id : null}
            onPick={pick}
            q={q} setQ={setQ}
            levelFilter={levelFilter} setLevelFilter={setLevelFilter}
          />
          {agent ? (
            <AgentProfile key={agent.id} A={A} agent={agent} goto={goto} />
          ) : (
            <div className="card"><div className="t-cap">No agent selected.</div></div>
          )}
        </div>
      </div>
    </div>
  );
}

Object.assign(window, { ATPAgents });
